#!/usr/bin/env python3
"""Focused optional QA against local rebuild/core; no app/runtime dependency."""
import argparse,hashlib,json,struct,subprocess,sys,tempfile
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--rom',type=Path,required=True);p.add_argument('--rebuild',type=Path,default=Path('../taikou-rebuild'));p.add_argument('--out',type=Path,default=Path('local-artifacts/japan-editor/native'));args=p.parse_args();root=args.rebuild.resolve();out=args.out.resolve();out.mkdir(parents=True,exist_ok=True);rom=args.rom.resolve();b=rom.read_bytes();assert b[-16:-8]==b'TKWNAV01';start,size=struct.unpack_from('>2I',b,len(b)-8);assert b[start:start+8] in (b'TKWNAVD2',b'TKWNAVD3');nav=json.loads(b[start+16:start+4096].rstrip(b'\0'));r=json.loads((root/'reports/map-expansion-japan-gates-build.json').read_text());r['output']=str(rom);r['output_sha256']=hashlib.sha256(b).hexdigest()
for mode,g in nav['components'].items():r['component_graphs'][mode].update({'map_offset':hex(g['map']),'nodes_offset':hex(g['nodesAt']),'nodes':g['nodes'],'edges':g['edges']})
report=out/'export-layout.json';report.write_text(json.dumps(r)+'\n');prefix='import sys\nsys.path.insert(0,'+repr(str(root/'tools'))+')\n'
with tempfile.TemporaryDirectory() as td:
 s=(root/'tools/test_japan_byte_routes_native.py').read_text().replace("'reports/map-expansion-japan-build.json'",repr(str(report))).replace("'reports/map-expansion-japan-byte-routes-native.json'",repr(str(out/'routes-native.json')));f=Path(td)/'routes.py';f.write_text(prefix+s);subprocess.run([sys.executable,str(f)],check=True,cwd=root)
 s=(root/'tools/test_west_honshu_live.py').read_text().replace("'reports/map-expansion-japan-build.json'",repr(str(report))).replace("'build/map-expansion/japan-integrated'",repr(str(out))).replace("f'reports/map-expansion-japan-{args.suite}-live-native.json'",'f'+repr(str(out)+'/{args.suite}-live-native.json'));f=Path(td)/'ocean.py';f.write_text(prefix+s);subprocess.run([sys.executable,str(f),'--profile','japan','--suite','ocean'],check=True,cwd=root)
 s=(root/'tools/test_west_new_town_live.py').read_text().replace("'reports/map-expansion-japan-gates-build.json'",repr(str(report))).replace("'build/map-expansion/japan-gates'",repr(str(out))).replace("f'reports/map-expansion-japan-gates-town{args.town}-live-native.json'",'f'+repr(str(out)+'/{args.town}-town-live-native.json'));f=Path(td)/'town.py';f.write_text(prefix+s);subprocess.run([sys.executable,str(f),'--profile','japan-gates','--town','20'],check=True,cwd=root)
print('PASS exported ROM native routes, ocean links and relocated town enter/walk/exit',r['output_sha256'])
